import { test, expect } from 'playwright/test';

const TEST_PASSWORD = "NexxusTest2026";

async function loginAs(page: import('playwright/test').Page, email: string) {
  const loginRes = await page.request.post('/api/auth/login', {
    data: { email, password: TEST_PASSWORD },
  });
  expect(loginRes.ok()).toBeTruthy();
  await page.addInitScript(() => {
    const prefix = 'nexxus_tour_dismissed_';
    const keys = ['main', 'teambox', 'my-work', 'sales', 'service', 'marketing',
      'management', 'agents', 'insights', 'settings', 'profile', 'usage'];
    for (const key of keys) localStorage.setItem(prefix + key, 'true');
  });
}

test.describe('Dashboard & Metrics', () => {
  test('Dashboard loads with metric tiles', async ({ page }) => {
    await loginAs(page, 'orgadmin@serrahonda.com');
    await page.goto('/', { waitUntil: 'domcontentloaded', timeout: 15000 });
    await expect(page.getByText('AI Key Metrics')).toBeVisible({ timeout: 10000 });
    await expect(page.getByText('Active Pipeline')).toBeVisible();
    await expect(page.getByText('Appointments Today')).toBeVisible();
    await expect(page.getByText('Open Escalations')).toBeVisible();
    await expect(page.getByText('Outbound Sent 24h')).toBeVisible();
    await expect(page.getByRole('textbox', { name: 'Ask me anything about your business' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'Show KPIs for this month' })).toBeVisible();
  });

  test('Dashboard metrics are role-specific', async ({ page }) => {
    await loginAs(page, 'sales@serrahonda.com');
    await page.goto('/', { waitUntil: 'domcontentloaded', timeout: 15000 });
    await expect(page.getByText('AI Key Metrics')).toBeVisible({ timeout: 10000 });
    const salesBody = await page.textContent('body') || '';
    expect(salesBody.length).toBeGreaterThan(100);
  });
});

