test.describe('TeamBox', () => {
  test('TeamBox shows conversations with filters', async ({ page }) => {
    await loginAs(page, 'orgadmin@serrahonda.com');
    await page.goto('/teambox', { waitUntil: 'domcontentloaded', timeout: 15000 });
    await page.getByRole('button', { name: 'Conversations' }).waitFor({ state: 'visible', timeout: 10000 });
    await expect(page.getByRole('button', { name: 'Conversations' })).toBeVisible();
    await expect(page.getByRole('button', { name: /Tasks/ })).toBeVisible();
    await expect(page.getByRole('button', { name: 'Workflows' })).toBeVisible();
    await expect(page.getByRole('button', { name: /All \d+/ })).toBeVisible();
    await expect(page.getByRole('button', { name: /Open \d+/ })).toBeVisible();
    await expect(page.getByRole('button', { name: 'SMS' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'Email' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'Voice' })).toBeVisible();
    await expect(page.getByRole('textbox', { name: 'Search conversations...' })).toBeVisible();
  });

  test('Clicking conversation shows message thread', async ({ page }) => {
    await loginAs(page, 'orgadmin@serrahonda.com');
    await page.goto('/teambox', { waitUntil: 'domcontentloaded', timeout: 15000 });
    await page.getByRole('button', { name: 'Conversations' }).waitFor({ state: 'visible', timeout: 10000 });
    const mcConv = page.getByRole('button', { name: /Michael Clark/ });
    if (await mcConv.count() > 0) {
      await mcConv.first().click();
      await expect(page.getByRole('textbox', { name: 'Write a reply...' })).toBeVisible({ timeout: 5000 });
    }
  });
});

